package sa.muslimtv.quran;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

/** A remote-first reader. Quran text is never retyped or generated by this application. */
public final class ReaderActivity extends Activity {
    private SharedPreferences prefs;
    private PageStore store;
    private ReaderView reader;
    private TextView heading, hint;
    private LinearLayout root;
    private int page;
    private volatile int generation;
    private boolean single;
    private volatile boolean alive = true;
    private int surface, accent;
    private JSONArray surahs, juz;
    private Typeface arabic;

    @Override public void onCreate(Bundle state) {
        super.onCreate(state);
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN, WindowManager.LayoutParams.FLAG_FULLSCREEN);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        prefs = getSharedPreferences("reader", MODE_PRIVATE);
        page = Math.max(1, Math.min(604, prefs.getInt("page", 1)));
        single = prefs.getBoolean("single", false);
        loadColors(getIntent());
        try { arabic = Typeface.createFromAsset(getAssets(), "NotoNaskhArabic.ttf"); } catch (Exception ignored) { arabic = Typeface.DEFAULT; }
        try (InputStream in = getAssets().open("index.json")) {
            ByteArrayOutputStream out = new ByteArrayOutputStream(); byte[] b = new byte[4096]; int n;
            while ((n = in.read(b)) != -1) out.write(b, 0, n);
            JSONObject data = new JSONObject(out.toString("UTF-8"));
            surahs = data.getJSONArray("surahs"); juz = data.getJSONArray("juz");
        } catch (Exception e) { throw new IllegalStateException("Missing mushaf index", e); }
        store = new PageStore(this);
        build(); showPage();
    }
    private void loadColors(Intent intent) {
        surface = intent.getIntExtra("theme_surface", prefs.getInt("surface", 0xFF182824));
        accent = intent.getIntExtra("theme_accent", prefs.getInt("accent", 0xFFD6AF6B));
        surface |= 0xFF000000; accent |= 0xFF000000;
        prefs.edit().putInt("surface", surface).putInt("accent", accent).apply();
    }
    @Override protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent); setIntent(intent); loadColors(intent); root.setBackgroundColor(surface); heading.setTextColor(accent);
    }
    private void build() {
        root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(dp(8), dp(4), dp(8), dp(4)); root.setBackgroundColor(surface);
        LinearLayout top = new LinearLayout(this); top.setOrientation(LinearLayout.HORIZONTAL);
        top.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
        hint = text("", 15, 0xFFCDC8BC); hint.setGravity(Gravity.LEFT | Gravity.CENTER_VERTICAL);
        hint.setSingleLine(true); hint.setEllipsize(android.text.TextUtils.TruncateAt.END);
        top.addView(hint, new LinearLayout.LayoutParams(0, -1, 1f));
        heading = text("", 22, accent); heading.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        heading.setSingleLine(true); heading.setEllipsize(android.text.TextUtils.TruncateAt.END);
        top.addView(heading, new LinearLayout.LayoutParams(0, -1, 1f));
        root.addView(top, new LinearLayout.LayoutParams(-1, dp(42)));
        reader = new ReaderView(); reader.setFocusable(true); reader.setOnClickListener(v -> menu());
        root.addView(reader, new LinearLayout.LayoutParams(-1, 0, 1));
        setContentView(root); reader.requestFocus();
    }
    private void directions() {
        hint.setText(single ? "▲▼ تمرير  ·  ◀▶ الصفحات  ·  OK الخيارات" : "◀ التالي  ·  السابق ▶  ·  OK الفهرس  ·  ▲ تكبير");
    }
    private void showPage() {
        final int token = ++generation;
        prefs.edit().putInt("page", page).putBoolean("single", single).apply();
        int first = single ? page : ((page - 1) / 2) * 2 + 1;
        final int second = single ? 0 : first + 1;
        if (!store.downloading.get()) directions();
        heading.setText("سورة " + surahName(page) + "  ·  الجزء " + ar(juzFor(page)));
        reader.setPages(first, second, null, null, false);
        // Drop queued obsolete navigation; one pair at a time limits memory on Fire TV Stick.
        store.reader.execute(() -> {
            if (!alive || token != generation) return;
            Bitmap right = null, left = null; boolean failed = false;
            try { right = store.load(first); } catch (IOException ignored) { failed = true; }
            if (second != 0 && first < 604) try { left = store.load(first + 1); } catch (IOException ignored) { failed = true; }
            final Bitmap r = right, l = left; final boolean error = failed;
            runOnUiThread(() -> {
                if (!alive || token != generation) { if (r != null) r.recycle(); if (l != null) l.recycle(); return; }
                reader.setPages(first, second, r, l, error);
                if (error && !store.downloading.get()) hint.setText("تعذر تحميل صفحة · OK لإعادة المحاولة");
            });
        });
    }
    private String pageLabel(int first) { return single ? "الصفحة " + ar(page) + " من ٦٠٤" : "الصفحتان " + ar(first) + " و" + ar(first + 1) + " من ٦٠٤"; }
    private String surahName(int p) {
        String name = "";
        for (int i = 0; i < surahs.length(); i++) if (surahs.optJSONObject(i).optInt("page") <= p) name = surahs.optJSONObject(i).optString("name");
        return name;
    }
    private int juzFor(int p) { int result = 1; for (int i = 0; i < juz.length(); i++) if (juz.optInt(i) <= p) result = i + 1; return result; }
    private void go(int target) { page = Math.max(1, Math.min(604, target)); showPage(); }
    @Override public boolean onKeyDown(int key, KeyEvent event) {
        if (key == KeyEvent.KEYCODE_DPAD_LEFT) { if (event.getRepeatCount() == 0) go(single ? page + 1 : ((page - 1) / 2) * 2 + 3); return true; }
        if (key == KeyEvent.KEYCODE_DPAD_RIGHT) { if (event.getRepeatCount() == 0) go(single ? page - 1 : ((page - 1) / 2) * 2 - 1); return true; }
        if (single && (key == KeyEvent.KEYCODE_DPAD_UP || key == KeyEvent.KEYCODE_DPAD_DOWN)) { reader.pan(key == KeyEvent.KEYCODE_DPAD_DOWN ? dp(72) : -dp(72)); return true; }
        if (key == KeyEvent.KEYCODE_DPAD_UP) { if (event.getRepeatCount() == 0) zoomMenu(); return true; }
        if (key == KeyEvent.KEYCODE_DPAD_DOWN || key == KeyEvent.KEYCODE_MENU) { if (event.getRepeatCount() == 0) menu(); return true; }
        if (key == KeyEvent.KEYCODE_BACK) {
            if (single) { single = false; showPage(); } else exitMenu(); return true;
        }
        return super.onKeyDown(key, event);
    }
    private void menu() {
        String[] labels = {"فهرس السور", "فهرس الأجزاء", "الانتقال إلى صفحة", single ? "عرض صفحتين" : "تكبير صفحة واحدة",
            "حفظ علامة هنا", "العودة إلى العلامة", store.downloading.get() ? "إيقاف تنزيل المصحف" : "تنزيل المصحف كاملًا دون إنترنت",
            "إعادة تحميل الصفحات الحالية", "عن المصحف ومصدر الصفحات", "العودة إلى القراءة"};
        dialog("المصحف الشريف", labels, which -> {
            switch (which) {
                case 0: index(false); break;
                case 1: index(true); break;
                case 2: pagePicker(); break;
                case 3: zoomMenu(); break;
                case 4: prefs.edit().putInt("bookmark", page).apply(); toast("حُفظت العلامة عند الصفحة " + ar(page)); break;
                case 5: go(prefs.getInt("bookmark", page)); break;
                case 6:
                    if (store.downloading.get()) store.cancelDownload();
                    else showArabic(new AlertDialog.Builder(this).setTitle("تنزيل المصحف كاملًا")
                        .setMessage("حوالي ٦١ ميغابايت للتنزيل. يُحفظ داخل التطبيق للقراءة دون إنترنت. أبقِ التطبيق مفتوحًا حتى يكتمل.\nالصفحات المتاحة الآن: " + ar(store.count()) + " / ٦٠٤")
                        .setPositiveButton("تنزيل", (d,w) -> store.downloadAll(message -> runOnUiThread(() -> {
                            if (alive) {
                                if (message.startsWith("جارٍ") || message.startsWith("تنزيل")) hint.setText(message);
                                else { directions(); if (!message.startsWith("اكتمل")) toast(message); }
                            }
                        }))).setNegativeButton("رجوع", null).create());
                    break;
                case 7: showPage(); break;
                case 8: showArabic(new AlertDialog.Builder(this).setTitle("مصحف MuslimTV")
                    .setMessage("مصحف المدينة · رواية حفص · ٦٠٤ صفحات\n\nالصور الأصلية دون تغيير: مشروع Quran Android / Quran.com Images، بخطوط مجمع الملك فهد.\nhttps://android.quran.com\nhttps://github.com/quran/quran.com-images\n\nفهرس أرقام الصفحات: Quran Android MadaniDataSource.\nخط القوائم: Noto Naskh Arabic (Google Fonts، OFL).\n\nتُحفظ آخر قراءة والعلامة على هذا الجهاز فقط. الصفحات تُنزّل من المصدر ولا يُولّد التطبيق نص المصحف. النسخة الأولى للقراءة دون تلاوة صوتية.")
                    .setPositiveButton("عودة", null).create()); break;
            }
        });
    }
    interface Pick { void selected(int index); }
    private void dialog(String title, String[] labels, Pick picked) {
        LinearLayout box = new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(18), dp(12), dp(18), dp(18)); box.setBackgroundColor(surface);
        TextView header = text(title, 26, accent); header.setGravity(Gravity.RIGHT); box.addView(header);
        ScrollView scroll = new ScrollView(this); LinearLayout rows = new LinearLayout(this); rows.setOrientation(LinearLayout.VERTICAL);
        scroll.addView(rows); box.addView(scroll, new LinearLayout.LayoutParams(-1, -2));
        AlertDialog alert = new AlertDialog.Builder(this).setView(box).create();
        TextView first = null;
        for (int i = 0; i < labels.length; i++) {
            final int choice = i;
            TextView row = text(labels[i], 20, 0xFFF4EEDC); row.setPadding(dp(18), dp(10), dp(18), dp(10));
            row.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL); row.setFocusable(true); row.setClickable(true);
            row.setOnFocusChangeListener((v, has) -> {
                GradientDrawable bg = new GradientDrawable(); bg.setCornerRadius(dp(10));
                bg.setColor(has ? accent : 0x10FFFFFF); row.setBackground(bg);
                row.setTextColor(has ? ink(accent) : 0xFFF4EEDC);
            });
            row.setOnClickListener(v -> { alert.dismiss(); picked.selected(choice); });
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, dp(51)); lp.topMargin = dp(5); rows.addView(row, lp);
            if (first == null) first = row;
        }
        alert.show(); alert.getWindow().setLayout(dp(590), Math.min(dp(455), getResources().getDisplayMetrics().heightPixels - dp(36)));
        if (first != null) first.requestFocus();
    }
    private void index(boolean parts) {
        int count = parts ? juz.length() : surahs.length(); String[] labels = new String[count];
        for (int i = 0; i < count; i++) labels[i] = parts ? "الجزء " + ar(i + 1)
            : ar(i + 1) + "   " + surahs.optJSONObject(i).optString("name");
        gridIndex(parts ? "فهرس الأجزاء" : "فهرس السور", labels, which -> go(parts ? juz.optInt(which) : surahs.optJSONObject(which).optInt("page")));
    }
    private void gridIndex(String title, String[] labels, Pick picked) {
        LinearLayout box = new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(18), dp(12), dp(18), dp(12)); box.setBackgroundColor(surface);
        TextView header = text(title, 26, accent); header.setGravity(Gravity.RIGHT);
        box.addView(header, new LinearLayout.LayoutParams(-1, dp(50)));
        ScrollView scroll = new ScrollView(this);
        LinearLayout rows = new LinearLayout(this); rows.setOrientation(LinearLayout.VERTICAL);
        rows.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
        int windowWidth = getResources().getDisplayMetrics().widthPixels - dp(56);
        TextView[] cells = new TextView[labels.length];
        AlertDialog alert = new AlertDialog.Builder(this).setView(box).create();
        for (int start = 0; start < labels.length; start += 4) {
            LinearLayout row = new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL);
            row.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
            for (int column = 3; column >= 0; column--) {
                int i = start + column;
                LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0, dp(54), 1);
                lp.setMargins(dp(2), dp(2), dp(2), dp(2));
                if (i >= labels.length) { row.addView(new View(this), lp); continue; }
                final int choice = i;
                TextView cell = text(labels[i], 18, 0xFFF4EEDC);
                cell.setGravity(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
                cell.setSingleLine(true);
                cell.setEllipsize(android.text.TextUtils.TruncateAt.END);
                cell.setPadding(dp(8), 0, dp(8), 0);
                cell.setId(View.generateViewId()); cell.setFocusable(true); cell.setClickable(true);
                cell.setOnFocusChangeListener((v, has) -> {
                    GradientDrawable bg = new GradientDrawable(); bg.setCornerRadius(dp(8));
                    bg.setColor(has ? accent : 0x10FFFFFF); cell.setBackground(bg);
                    cell.setTextColor(has ? ink(accent) : 0xFFF4EEDC);
                });
                cell.setOnClickListener(v -> { alert.dismiss(); picked.selected(choice); });
                row.addView(cell, lp); cells[i] = cell;
            }
            rows.addView(row, new LinearLayout.LayoutParams(-1, dp(58)));
        }
        for (int i = 0; i < cells.length; i++) {
            cells[i].setNextFocusLeftId(cells[i % 4 == 3 || i + 1 >= cells.length ? i : i + 1].getId());
            cells[i].setNextFocusRightId(cells[i % 4 == 0 ? i : i - 1].getId());
            cells[i].setNextFocusUpId(cells[i < 4 ? i : i - 4].getId());
            cells[i].setNextFocusDownId(cells[Math.min(i + 4, cells.length - 1)].getId());
        }
        scroll.addView(rows); box.addView(scroll, new LinearLayout.LayoutParams(-1, 0, 1));
        alert.show();
        alert.getWindow().setLayout(windowWidth, getResources().getDisplayMetrics().heightPixels - dp(38));
        if (cells.length > 0) cells[0].requestFocus();
    }
    private void zoomMenu() {
        if (single) { single = false; showPage(); return; }
        int first = ((page - 1) / 2) * 2 + 1;
        dialog("تكبير صفحة واحدة", new String[]{"الصفحة اليمنى · " + ar(first), "الصفحة اليسرى · " + ar(first + 1)}, which -> { single = true; go(first + which); });
    }
    private void pagePicker() {
        // Remote-only picker: no touch keyboard or text entry required.
        LinearLayout box = new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setPadding(dp(25), dp(12), dp(25), dp(12));
        NumberPicker picker = new NumberPicker(this); picker.setMinValue(1); picker.setMaxValue(604); picker.setValue(page);
        picker.setWrapSelectorWheel(false); picker.setDescendantFocusability(NumberPicker.FOCUS_BLOCK_DESCENDANTS); picker.setFormatter(ReaderActivity::ar);
        box.addView(picker);
        showArabic(new AlertDialog.Builder(this).setTitle("اختر الصفحة · ▲▼ للتغيير").setView(box)
            .setPositiveButton("انتقال", (d,w) -> go(picker.getValue())).setNegativeButton("رجوع", null).create());
        picker.requestFocus();
    }
    private void exitMenu() { showArabic(new AlertDialog.Builder(this).setTitle("الخروج من المصحف؟").setMessage("حُفظ موضع القراءة تلقائيًا.")
        .setPositiveButton("خروج", (d,w) -> finish()).setNegativeButton("متابعة القراءة", null).create()); }
    private void showArabic(AlertDialog dialog) { dialog.show(); applyArabic(dialog.getWindow().getDecorView()); }
    private void applyArabic(View view) {
        if (view instanceof TextView) ((TextView) view).setTypeface(arabic);
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) applyArabic(group.getChildAt(i));
        }
    }
    private TextView text(String value, int size, int color) { TextView t = new TextView(this); t.setText(value); t.setTextSize(size); t.setTextColor(color); t.setTypeface(arabic); return t; }
    private void toast(String value) { Toast.makeText(this, value, Toast.LENGTH_SHORT).show(); }
    private int dp(int v) { return Math.round(v * getResources().getDisplayMetrics().density); }
    private int ink(int color) { return Color.red(color) * .2126 + Color.green(color) * .7152 + Color.blue(color) * .0722 > 155 ? Color.BLACK : Color.WHITE; }
    static String ar(int number) { StringBuilder b = new StringBuilder(); for (char c : String.valueOf(number).toCharArray()) b.append(c >= '0' && c <= '9' ? (char)('٠' + c - '0') : c); return b.toString(); }
    @Override protected void onDestroy() { alive = false; generation++; store.close(); reader.release(); super.onDestroy(); }

    private final class ReaderView extends View {
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);
        private Bitmap right, left;
        private int first, second;
        private boolean error;
        private float offset, maximumOffset;
        void pan(float amount) { offset = Math.max(0, Math.min(maximumOffset, offset + amount)); invalidate(); }
        ReaderView() { super(ReaderActivity.this); setContentDescription("صفحات المصحف. يسار للتالي، يمين للسابق، وموافق للفهرس"); }
        void release() { if (right != null) right.recycle(); if (left != null) left.recycle(); right = left = null; }
        void setPages(int first, int second, Bitmap right, Bitmap left, boolean error) { release(); this.first = first; this.second = second; this.right = right; this.left = left; this.error = error; offset = 0; invalidate(); }
        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float gap = dp(8), viewportHeight = getHeight() - dp(4);
            Bitmap sample = right != null ? right : left;
            float aspect = sample == null ? 2038f / 1260f : (float) sample.getHeight() / sample.getWidth();
            float halfWidth = (getWidth() - gap) / 2f;
            // The full double-page image must remain visible and retain its original proportions.
            float width = second == 0 ? getWidth() - dp(4)
                : Math.min(halfWidth, (viewportHeight - dp(24)) / aspect + dp(10));
            float height = second == 0 ? Math.max(viewportHeight, (width - dp(10)) * aspect + dp(24)) : viewportHeight;
            maximumOffset = second == 0 ? Math.max(0, height - getHeight() + dp(4)) : 0;
            canvas.save(); canvas.clipRect(0, 0, getWidth(), getHeight()); canvas.translate(0, -offset);
            float total = second == 0 ? width : width * 2 + gap, start = (getWidth() - total) / 2;
            if (second != 0) drawPage(canvas, left, second, start, width, height);
            drawPage(canvas, right, first, second == 0 ? start : start + width + gap, width, height);
            canvas.restore();
        }
        private void drawPage(Canvas canvas, Bitmap image, int number, float x, float width, float height) {
            RectF paper = new RectF(x, dp(3), x + width, height);
            paint.setColor(0xFFF9F5E9); canvas.drawRoundRect(paper, dp(5), dp(5), paint);
            float border = dp(5), foot = dp(18);
            if (image != null) {
                // Preserve the original page proportions. Only the optional single-page zoom scrolls.
                float imageHeight = (width - border * 2) * image.getHeight() / image.getWidth();
                RectF dest = new RectF(x + border, border, x + width - border, border + imageHeight);
                paint.setColor(Color.WHITE); canvas.drawBitmap(image, null, dest, paint);
            } else {
                paint.setColor(0xFF3D4840); paint.setTextSize(dp(18)); paint.setTypeface(arabic); paint.setTextAlign(Paint.Align.CENTER);
                canvas.drawText(error ? "الصفحة غير متاحة دون اتصال" : "جارٍ تحميل الصفحة…", x + width / 2, height / 2, paint);
            }
            paint.setColor(0xFF535047); paint.setTextSize(dp(13)); paint.setTypeface(arabic); paint.setTextAlign(Paint.Align.CENTER);
            canvas.drawText(ar(number), x + width / 2, height - dp(7), paint);
        }
    }
}
